<section id="overview" class="tb-portal-card tb-workspace-section"><p class="tb-card-kicker">OVERVIEW</p><h2>Project Brief</h2><div class="tb-meta-grid"><div><small>Service</small><strong><?php echo esc_html($services[$service]??$service);?></strong></div><div><small>Status</small><strong><?php echo esc_html(tuff_beatz_request_status_label($status));?></strong></div><div><small>Genre</small><strong><?php echo esc_html(get_post_meta($request_id,'_tb_request_genre',true)?:'—');?></strong></div><div><small>BPM / Key</small><strong><?php echo esc_html((get_post_meta($request_id,'_tb_request_bpm',true)?:'—').' / '.(get_post_meta($request_id,'_tb_request_key',true)?:'—'));?></strong></div><div><small>Tracks / Stems</small><strong><?php echo esc_html(get_post_meta($request_id,'_tb_request_track_count',true)?:'—');?></strong></div><div><small>Target Date</small><strong><?php echo esc_html(get_post_meta($request_id,'_tb_request_target_date',true)?:'—');?></strong></div></div><div class="tb-project-copy"><h3>Creative Direction</h3><p><?php echo nl2br(esc_html(get_post_meta($request_id,'_tb_request_details',true)));?></p></div></section>
