<section id="review" class="tb-portal-card tb-workspace-section"><p class="tb-card-kicker">MIX REVIEW V4</p><h2>Listen. Comment. Approve.</h2><p class="tb-vault-note">Play a mix, stop at the exact moment you want changed, capture the timestamp, and leave a revision note.</p><?php if($review_files):?><div class="tb-review-stack"><?php foreach(array_reverse($review_files) as $f):$fid=$f['id'];$player='tb-audio-'.preg_replace('/[^a-zA-Z0-9_-]/','',$fid);$rs=tuff_beatz_review_status($request_id,$fid);$notes=array_values(array_filter($review_notes,function($n)use($fid){return ($n['file_id']??'')===$fid;}));?><article class="tb-review-version" data-tb-review><div class="tb-review-head"><div><span><?php echo esc_html($f['version']?:'Mix Version');?></span><strong><?php echo esc_html($f['name']);?></strong></div><b class="tb-review-state tb-review-state--<?php echo esc_attr($rs);?>"><?php echo esc_html(str_replace('-',' ',$rs));?></b></div><audio id="<?php echo esc_attr($player);?>" controls preload="metadata" src="<?php echo esc_url(tuff_beatz_vault_download_url($request_id,$fid));?>"></audio><div class="tb-review-clock">Current position: <strong data-review-time>0:00</strong></div><?php if($notes):?><div class="tb-review-notes"><?php foreach($notes as $n):$sec=(int)($n['seconds']??0);?><div><button type="button" data-player="<?php echo esc_attr($player);?>" data-jump-time="<?php echo esc_attr($sec);?>"><?php echo esc_html(sprintf('%d:%02d',floor($sec/60),$sec%60));?></button><p><strong><?php echo esc_html($n['name']??'Client');?></strong> <?php echo esc_html($n['body']??'');?></p></div><?php endforeach;?></div><?php endif;?><?php if($rs!=='approved'):?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>" class="tb-review-form"><input type="hidden" name="action" value="tb_submit_mix_review"><input type="hidden" name="request_id" value="<?php echo esc_attr($request_id);?>"><input type="hidden" name="file_id" value="<?php echo esc_attr($fid);?>"><input type="hidden" name="timestamp" value="0"><?php wp_nonce_field('tb_mix_review_'.$request_id.'_'.$fid,'tb_review_nonce');?><button class="btn btn-outline" type="button" data-mark-time>Mark Current Time</button><textarea name="review_note" required placeholder="Example: Bring the lead vocal up 1 dB here, reduce the delay, tighten the background vocals..."></textarea><button class="btn btn-gold" type="submit">Request Revision</button></form><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>" class="tb-approve-form" onsubmit="return confirm('Approve this mix and move the project to Mastering?');"><input type="hidden" name="action" value="tb_approve_mix"><input type="hidden" name="request_id" value="<?php echo esc_attr($request_id);?>"><input type="hidden" name="file_id" value="<?php echo esc_attr($fid);?>"><?php wp_nonce_field('tb_approve_mix_'.$request_id.'_'.$fid,'tb_approve_nonce');?><button class="btn btn-gold" type="submit">✓ Approve Mix → Mastering</button></form><?php else:?><div class="tb-approved-banner">✓ APPROVED FOR MASTERING</div><?php endif;?></article><?php endforeach;?></div><?php else:?><p class="tb-empty-state">No review mix has been uploaded yet. When TUFF BEATZ uploads Mix V1, Mix V2 or another audio version, it will appear here.</p><?php endif;?></section>
<section id="messages" class="tb-portal-card tb-workspace-section"><p class="tb-card-kicker">MESSAGES</p><h2>Project Conversation</h2><div class="tb-message-list"><?php if($messages):foreach($messages as $m):?><article class="tb-message"><div><strong><?php echo esc_html($m['name']??'User');?></strong><span><?php echo esc_html($m['role']??'Client');?> • <?php echo esc_html(mysql2date('M j, Y g:i a',$m['time']??''));?></span></div><p><?php echo nl2br(esc_html($m['body']??''));?></p></article><?php endforeach;else:?><p class="tb-empty-state">No messages yet.</p><?php endif;?></div><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>" class="tb-message-form"><input type="hidden" name="action" value="tb_submit_project_message"><input type="hidden" name="request_id" value="<?php echo esc_attr($request_id);?>"><?php wp_nonce_field('tb_project_message_'.$request_id,'tb_message_nonce');?><textarea name="message" rows="4" required placeholder="Write a project message..."></textarea><button class="btn btn-gold" type="submit">Send Message</button></form></section>
<section id="credits" class="tb-portal-card tb-workspace-section"><p class="tb-card-kicker">CREDITS</p><h2>Personnel & Credits</h2><?php echo $credits?'<p class="tb-preline">'.nl2br(esc_html($credits)).'</p>':'<p class="tb-empty-state">Credits have not been finalized yet.</p>';?></section><section id="payments" class="tb-portal-card tb-workspace-section"><p class="tb-card-kicker">PAYMENTS</p><h2>Financial Status</h2><div class="tb-payment-card"><span>PROJECT PAYMENT STATUS</span><strong><?php echo esc_html($payment);?></strong></div></section>
